    Assertions.assertNull(migrationRuleListener.localRuleMigrationFuture);
    Assertions.assertNull(migrationRuleListener.ruleMigrationFuture);
    Assertions.assertEquals(0, migrationRuleListener.ruleQueue.size());
}

