    Assertions.assertNotNull(l, "cluster.initLoadBalance returns null!");
    {
        selectedInvokers.clear();
        selectedInvokers.add(invoker4);
        Invoker invoker = cluster.select(l, invocation, invokers, selectedInvokers);
