void testExecute() {
    PublishMetadata publishMetadata = new PublishMetadata(frameworkModel);
    String result = publishMetadata.execute(Mockito.mock(CommandContext.class), new String[0]);
    String expectResult = "publish metadata succeeded. App:APP_0\n" + "publish metadata succeeded. App:APP_1\n" + "publish metadata succeeded. App:APP_2\n";
