    Assertions.assertEquals(result, expectResult);
    // wrong delay param
    result = publishMetadata.execute(Mockito.mock(CommandContext.class), new String[] { "A" });
    expectResult = "publishMetadata failed! Wrong delay param!";
    Assertions.assertEquals(result, expectResult);
}

